// PopulateEventMetadata stores pending event metadata (W3C SCXML 5.10).
// Note: event name is set separately via setCurrentEvent(); metadata supplies
// only the name the event ARRIVED under, when that is not its value's own.
func (p *AskerPolicy) PopulateEventMetadata(meta *sce.EventMetadata) {
	// NL→IR Item C1 Path A: lift the dequeued event's typed payload from the
	// type-erased carrier into the typed policy field the native guards read
	// (twin of the C11 pop loop's `sm->pending_payload = evt.payload`).
	p.pendingPayloadTag = AskerPayloadTagNone
	switch v := meta.TypedPayload.(type) {
	case AskerJobReplyPayload:
		p.pendingPayloadTag = AskerPayloadTagJobReply
		p.pendingJobReplyPayload = v
	}

	p.pendingEventData = meta.Data
	p.pendingEventInvokeid = meta.InvokeID
}

// LiftTypedPayload binds the dequeued event's typed `_event.data` view from
// the data it carries (NL→IR Item C1 Path A).
//
// The typed carrier PopulateEventMetadata reads is filled by one producer, the
// generated Raise<Event> inject seam. Every other producer — <send> with
// <param>, an invoke forwarding either way, autoforward, BasicHTTP, mesh —
// fills EventMetadata.Data, so the schema's fields are read out of that here.
// A refusal is returned for the engine to raise as error.execution, which is
// what W3C SCXML 3.13 gives for a guard that cannot be evaluated.
func (p *AskerPolicy) LiftTypedPayload(event AskerEvent, meta *sce.EventMetadata) error {
	// A typed carrier already bound the view, so the producer was the
	// inject seam and there is nothing to read out of `Data`.
	if p.pendingPayloadTag != AskerPayloadTagNone {
		return nil
	}
	switch event {
	case AskerEventJobReply:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload AskerJobReplyPayload
		if payload.job, err = sce.PayloadUnsigned[uint32](fields, "job"); err != nil {
			return err
		}
		if payload.code, err = sce.PayloadUnsigned[uint32](fields, "code"); err != nil {
			return err
		}
		p.pendingJobReplyPayload = payload
		p.pendingPayloadTag = AskerPayloadTagJobReply
	}
	return nil

}

// ClearEventMetadata resets pending event metadata (W3C SCXML 5.10).
func (p *AskerPolicy) ClearEventMetadata() {
	// NL→IR Item C1 Path A: reset the typed-payload tag (PopulateEventMetadata
	// always re-establishes it for the next event; this keeps a stale payload
	// from being read between macrosteps).
	p.pendingPayloadTag = AskerPayloadTagNone

	p.pendingEventData = ""
	p.pendingEventInvokeid = ""
}



// ExecuteEntryActions enters one state (W3C SCXML 3.8): adds it to the
// configuration, runs its <onentry>, and its <initial> transition's content when
// its initial state is entered by default.
//line asker.scxml:7
func (p *AskerPolicy) ExecuteEntryActions(state AskerState, engine *sce.Engine[AskerState, AskerEvent], isDefaultEntry bool) {
	switch state {
	case AskerStateAsking:
//line asker.scxml:21
		// W3C SCXML 3.8 + 4.9: onentry block 0, its own function so an
		// error ends it with `return` from however deep a <foreach> it came.
		func() {

	// W3C SCXML 6.2: send id="__send_0"
	{
	{
		eventDataStr := ""
		_ = eventDataStr
	// §scxml-6.2.5: "http://sce.dev/ext/test-port" is served by the host, which
	// declared it to this build. Dispatch rather than refuse — and take the
	// whole send, because a processor the host serves owns delivery; falling
	// through would also enqueue the event locally and the document would see
	// the act twice.
	{
		hostParams := map[string][]string{}
		hostRequest := sce.HostSendRequest{
			ProcessorType: "http://sce.dev/ext/test-port",
			EventName:     "job.request",
			Target:        "sut",
			Content:       "",
			Params:        hostParams,
			SendID:        "__send_0",
			// W3C SCXML 5.10: the payload computed above, once, for every arm.
			EventData: eventDataStr,
			// SCE_MESH.md §mesh-10.7: the invokeid of the event being
			// processed now, carried back out as a W3C child's send to its
			// parent carries it (§scxml-6.4.1). Analysis keeps the field on
			// every machine with a host-served send.
			InvokeID: p.pendingEventInvokeid,
			// docs/SCE_TEST_PROFILE.md §12.3: a test component's message is the
			// value of its specific template, handed to the test-port processor
			// as a value and never as an encoding (docs/adr/0091, C2). Every
			// other send leaves it nil and carries EventData.
			Value: sce_request_of.Specific(p.vJob),
		}
		_, hostServed := engine.PerformHostSend(hostRequest)
		// W3C SCXML 6.2: a declared type with no handler registered is, from
		// the document's side, a processor the platform does not support — the
		// act it asked for was performed by nobody. Same event as an
		// undeclared type, so a wiring mistake cannot read as success.
		if !hostServed && !engine.HasEventProcessor("http://sce.dev/ext/test-port") {
			errEvt := sce.NewPlatformError(AskerEventErrorExecution, "<send type='http://sce.dev/ext/test-port'> names a processor the host declared but never registered")
			errEvt.Metadata.SendID = "__send_0"
			engine.Raise(errEvt)
		}
	}
	}
	}

	// docs/SCE_TEST_PROFILE.md §4.7: <sce:start-timer>

	p.sceTestContext.StartTimer("reply", 1000000)

		}()
	default:
		// No entry actions
	}
}

