// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line asker.scxml:7
func (p *AskerPolicy) FirstEnabledTransition(state AskerState, event AskerEvent, engine *sce.Engine[AskerState, AskerEvent]) (sce.EnabledTransition[AskerState, sce.HistoryID], bool) {
	switch state {
	case AskerStateAsking:
		if event == AskerEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if scetestprofile.Receives(p.sceTestContext, "sut", "job.reply", func(sceMessage sce_reply_ok.Value) bool { return sce_reply_ok.Matches(sceMessage) }) {
				return sce.EnabledTransition[AskerState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfAsker[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
		if event == AskerEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.TimedOut("reply") {
				return sce.EnabledTransition[AskerState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfAsker[state][1],
					TransitionIndex: 1,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	case AskerStateChecking:
		if event == AskerEventNull {
			// NL→IR Item C1 Path A: native typed `_event.data` guard — cond
			// "answered === job" lowered to a tag-checked field comparison on
			// the lifted `pending<Event>Payload` (no script engine).
			if p.vAnswered == p.vJob {
				return sce.EnabledTransition[AskerState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfAsker[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
		if event == AskerEventNull {
			{
				return sce.EnabledTransition[AskerState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfAsker[state][1],
					TransitionIndex: 1,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[AskerState, sce.HistoryID]{}, false
}

